"""Nexus IT Pack: Backend Engineer Agent."""
from __future__ import annotations

from pydantic import BaseModel, Field
from nexus.providers.base import BaseModelProvider
from nexus.teams.it_pack.ba import ProductProposal
from nexus.teams.it_pack.manager import SprintPlan


class BackendSpecification(BaseModel):
    """Complete backend code generated by the Backend Engineer."""
    entry_point_code: str = Field(description="Complete main.py code using create_nexus_app()")
    models_code: str = Field(description="Pydantic and SQLAlchemy database models code")


class BackendEngineerAgent:
    """
    Backend Engineer Agent in the Nexus Core IT Pack.
    Implements production-ready FastAPI routes, Gemini 3.8 integration, and data models.
    """

    def __init__(self, provider: BaseModelProvider) -> None:
        self.provider = provider

    def build_backend(self, proposal: ProductProposal, plan: SprintPlan) -> BackendSpecification:
        """Generate backend FastAPI and data model code."""
        prompt = f"""You are a Senior Backend Engineer building on the Nexus Platform Framework.
Build the backend implementation for:
App: {proposal.title} ({proposal.app_name})
API Endpoints needed: {', '.join(plan.api_endpoints)}
Database Entities: {', '.join(plan.database_entities)}

Generate:
1. `entry_point_code`: A complete FastAPI service using `from nexus.api import create_nexus_app` and `from nexus.ai import GeminiClient`. Include mock or live handlers for the requested endpoints.
2. `models_code`: Pydantic input/output schemas and Nexus database entity models.
"""
        system = "You are a pragmatic, high-velocity Senior Python engineer adhering to clean architecture."
        return self.provider.structured(prompt, BackendSpecification, system_instruction=system)
